<script setup lang="ts">import {Head,Link,useForm} from '@inertiajs/vue3';const props=defineProps<{values:Record<string,any>}>();const form=useForm(Object.fromEntries(Object.entries(props.values).map(([k,v])=>[k.replaceAll('.','_'),v])) as Record<string,any>);const fields=[['pmb_registration_fee','Harga Pendaftaran (Rp)','number'],['duitku_mode','Mode Duitku','select'],['duitku_merchant_code','Merchant code','password'],['duitku_api_key','API key','password'],['fonnte_base_url','Base URL Fonnte','url'],['fonnte_token','Token Fonnte','password'],['mail_host','SMTP host','text'],['mail_port','SMTP port','number'],['mail_username','SMTP username','password'],['mail_password','SMTP app password','password'],['mail_from_address','From address','email']];</script>
<template><Head title="Pengaturan Integrasi"/><main class="min-h-screen bg-slate-100 p-5"><section class="mx-auto max-w-3xl"><Link href="/admin/dashboard" class="text-emerald-700">← Dashboard</Link><h1 class="text-3xl font-bold text-emerald-950">Pengaturan integrasi</h1><p class="mt-2 text-sm text-slate-600">Nilai rahasia terenkripsi dan tidak pernah dikirim kembali ke browser. Biarkan nilai bertanda titik tetap untuk mempertahankan secret lama.</p><form @submit.prevent="form.put('/admin/settings')" class="mt-6 grid gap-5 rounded-2xl bg-white p-7 md:grid-cols-2"><label v-for="[key,label,type] in fields" :key="key" class="block"><span class="text-sm font-semibold">{{label}}</span><select v-if="type==='select'" v-model="form[key]" class="mt-1 w-full rounded-xl border-slate-300"><option value="sandbox">Sandbox</option><option value="production">Production</option></select><input v-else v-model="form[key]" :type="type" class="mt-1 w-full rounded-xl border-slate-300" autocomplete="off"/><small class="text-red-700">{{form.errors[key]}}</small></label><button class="rounded-xl bg-emerald-800 py-3 font-bold text-white md:col-span-2">Simpan pengaturan</button></form></section></main></template>

